-- create "content_publish_schedules" table
CREATE TABLE "content_publish_schedules" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "shop_id" bigint NOT NULL, "doc_key" character varying(63) NOT NULL, "draft_rev" bigint NOT NULL, "publish_at" timestamptz NOT NULL, "status" character varying(20) NOT NULL DEFAULT 'pending', "result" character varying(30) NOT NULL DEFAULT '', "failure" jsonb NULL, "attempts" bigint NOT NULL DEFAULT 0, "late_seconds" bigint NOT NULL DEFAULT 0, "created_by_user_id" bigint NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "claimed_at" timestamptz NULL, "finished_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "content_publish_schedules_status_check" CHECK ((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'done'::character varying, 'failed'::character varying, 'missed'::character varying, 'cancelled'::character varying, 'superseded'::character varying])::text[])));
-- create index "contentschedule_shop_id_doc_key" to table: "content_publish_schedules"
CREATE UNIQUE INDEX "contentschedule_shop_id_doc_key" ON "content_publish_schedules" ("shop_id", "doc_key") WHERE ((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying])::text[]));
-- create index "contentschedule_shop_id_publish_at" to table: "content_publish_schedules"
CREATE INDEX "contentschedule_shop_id_publish_at" ON "content_publish_schedules" ("shop_id", "publish_at");
-- create index "contentschedule_status_publish_at" to table: "content_publish_schedules"
CREATE INDEX "contentschedule_status_publish_at" ON "content_publish_schedules" ("status", "publish_at");
